     1	/**
     2	 * What insured items contribute to a premium, before policy-wide modifiers.
     3	 *
     4	 * The two contributions are kept apart all the way up because policy-wide
     5	 * modifiers scale only the policy base premium: a risk surcharge has already
     6	 * been assessed against its own item and must not be scaled again.
     7	 */
     8	export interface ItemPricing {
     9	  /** Sum of item base premiums -- the policy base premium. */
    10	  readonly basePremium: number;
    11	  /** Item-specific risk surcharges, each on its own item's base premium. */
    12	  readonly riskSurcharges: number;
    13	}
    14	
    15	/** An item that contributes nothing -- the identity for combining pricings. */
    16	export const NO_PRICING: ItemPricing = { basePremium: 0, riskSurcharges: 0 };
    17	
    18	/**
    19	 * Pricings combine by adding each contribution separately: base premiums
    20	 * accumulate into the policy base premium, and risk surcharges accumulate
    21	 * alongside it, because policy-wide modifiers scale only the former.
    22	 */
    23	export function combinedPricing(
    24	  left: ItemPricing,
    25	  right: ItemPricing,
    26	): ItemPricing {
    27	  return {
    28	    basePremium: left.basePremium + right.basePremium,
    29	    riskSurcharges: left.riskSurcharges + right.riskSurcharges,
    30	  };
    31	}
